import { StatusBar } from 'expo-status-bar';
import { useEffect, useMemo, useState } from 'react';
import { Alert, Modal, Pressable, SafeAreaView, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { ArrowDownLeft, ArrowUpRight, Banknote, BarChart3, Bell, ChevronLeft, ChevronRight, CreditCard, Landmark, MoreHorizontal, Pencil, Plus, Receipt, Search, Send, Settings, ShoppingBag, Trash2, Utensils, Wallet, X } from 'lucide-react-native';
import { Account, Category, formatMoney, loadStore, palette, Profile, saveStore, Store, Transaction } from './src/store';
import { settingsStyles } from './src/settingsStyles';
import { transactionStyles } from './src/transactionStyles';

type Tab = 'home' | 'activity' | 'accounts' | 'settings' | 'categories' | 'insights';

function Icon({ kind }: { kind: string }) {
  const props = { size: 18, color: palette.ink };
  if (kind === 'income') return <ArrowDownLeft {...props} color={palette.green} />;
  if (kind === 'food') return <Utensils {...props} />;
  if (kind === 'bag') return <ShoppingBag {...props} />;
  if (kind === 'transfer') return <Send {...props} />;
  return <Receipt {...props} />;
}

export default function App() {
  const [store, setStore] = useState<Store>({ accounts: [], transactions: [], categories: [], profile: { name: '', email: '' } });
  const [tab, setTab] = useState<Tab>('home');
  const [showAdd, setShowAdd] = useState(false);
  const [showAccountEditor, setShowAccountEditor] = useState(false);
  const [editingAccount, setEditingAccount] = useState<Account | undefined>();
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | undefined>();
  const [editingTransaction, setEditingTransaction] = useState<Transaction | undefined>();
  const [saved, setSaved] = useState(false);
  useEffect(() => { loadStore().then(setStore); }, []);
  useEffect(() => { if (store.accounts.length) saveStore(store); }, [store]);
  const total = useMemo(() => store.accounts.reduce((sum, item) => sum + item.balance, 0), [store]);
  const income = useMemo(() => store.transactions.filter(item => item.type === 'income').reduce((sum, item) => sum + item.amount, 0), [store]);
  const expenses = useMemo(() => Math.abs(store.transactions.filter(item => item.type === 'expense').reduce((sum, item) => sum + item.amount, 0)), [store]);
  function addTransaction(title: string, amount: number, type: 'expense' | 'income', accountId: string, categoryId: string) {
    const account = store.accounts.find(item => item.id === accountId) ?? store.accounts[0]; const signed = type === 'expense' ? -amount : amount;
    const category = store.categories.find(item => item.id === categoryId);
    setStore(current => ({ ...current, accounts: current.accounts.map(item => item.id === account.id ? { ...item, balance: item.balance + signed } : item), transactions: [{ id: Date.now().toString(), title, category: category?.name ?? (type === 'income' ? 'Income' : 'General'), categoryId: category?.id, amount: signed, type, date: 'Just now', account: account.name, accountId: account.id, icon: category?.icon ?? (type === 'income' ? 'income' : 'home') }, ...current.transactions] }));
    setShowAdd(false); setSaved(true); setTimeout(() => setSaved(false), 1800);
  }
  function saveAccount(account: Omit<Account, 'id'>, id?: string) {
    setStore(current => ({ ...current, accounts: id ? current.accounts.map(item => item.id === id ? { ...item, ...account } : item) : [...current.accounts, { ...account, id: Date.now().toString() }] }));
    setShowAccountEditor(false); setEditingAccount(undefined); setSaved(true); setTimeout(() => setSaved(false), 1800);
  }
  function deleteAccount(id: string) {
    setStore(current => ({ ...current, accounts: current.accounts.filter(item => item.id !== id) }));
    setSaved(true); setTimeout(() => setSaved(false), 1800);
  }
  function openTransaction(transaction: Transaction) { setSelectedTransaction(transaction); }
  function deleteTransaction(transaction: Transaction) {
    setStore(current => ({ ...current, accounts: current.accounts.map(account => account.id === transaction.accountId ? { ...account, balance: account.balance - transaction.amount } : account), transactions: current.transactions.filter(item => item.id !== transaction.id) }));
    setSelectedTransaction(undefined); setSaved(true); setTimeout(() => setSaved(false), 1800);
  }
  function updateTransaction(transaction: Transaction, title: string, amount: number, type: 'expense' | 'income', accountId: string, categoryId: string) {
    setStore(current => { const nextAccount = current.accounts.find(account => account.id === accountId) ?? current.accounts[0]; const category = current.categories.find(item => item.id === categoryId); const signed = type === 'expense' ? -amount : amount; const oldAccountId = transaction.accountId ?? current.accounts.find(account => account.name === transaction.account)?.id; const accounts = current.accounts.map(account => { if (account.id === oldAccountId) return { ...account, balance: account.balance - transaction.amount + (account.id === nextAccount.id ? signed : 0) }; if (account.id === nextAccount.id) return { ...account, balance: account.balance + signed }; return account; }); const updated = { ...transaction, title, amount: signed, type, account: nextAccount.name, accountId: nextAccount.id, category: category?.name ?? 'General', categoryId: category?.id, icon: category?.icon ?? 'home' }; return { ...current, accounts, transactions: current.transactions.map(item => item.id === transaction.id ? updated : item) }; });
    setEditingTransaction(undefined); setSelectedTransaction(undefined); setSaved(true); setTimeout(() => setSaved(false), 1800);
  }
  return <SafeAreaView style={styles.safe}><StatusBar style="dark" /><View style={styles.app}>
    <View style={styles.topbar}><View><Text style={styles.eyebrow}>SUNDAY, 23 JUNE</Text><Text style={styles.greeting}>Good morning, {store.profile.name.split(' ')[0] || 'there'}</Text></View><Pressable style={styles.iconButton}><Bell size={20} color={palette.ink} /><View style={styles.dot} /></Pressable></View>
    {tab === 'home' && <Dashboard store={store} total={total} income={income} expenses={expenses} onAdd={() => setShowAccountEditor(true)} onAccounts={() => setTab('accounts')} onTransactions={() => setTab('activity')} onTransaction={openTransaction} />}
    {tab === 'activity' && <Activity transactions={store.transactions} onTransaction={openTransaction} />}
    {tab === 'accounts' && <Accounts accounts={store.accounts} onAdd={() => setShowAccountEditor(true)} onEdit={account => { setEditingAccount(account); setShowAccountEditor(true); }} onDelete={deleteAccount} />}
    {tab === 'settings' && <ProfileSettings profile={store.profile} onProfileChange={profile => setStore(current => ({ ...current, profile }))} onCategories={() => setTab('categories')} onInsights={() => setTab('insights')} />}
    {tab === 'categories' && <CategoriesPage categories={store.categories} onChange={categories => setStore(current => ({ ...current, categories }))} onBack={() => setTab('settings')} />}
    {tab === 'insights' && <InsightsPage transactions={store.transactions} onBack={() => setTab('settings')} />}
    <View style={styles.bottomNav}>{[['home', 'Overview', <Wallet size={21} />], ['activity', 'Activity', <Receipt size={21} />], ['insights', 'Insights', <BarChart3 size={21} />], ['accounts', 'Accounts', <Landmark size={21} />], ['settings', 'Settings', <Settings size={21} />]].map(([key, label, icon]) => <Pressable key={String(key)} onPress={() => setTab(key as Tab)} style={styles.navItem}><View style={[styles.navIcon, tab === key && styles.navIconActive]}>{icon}</View><Text style={[styles.navLabel, tab === key && styles.navLabelActive]}>{label}</Text></Pressable>)}</View>
    <Pressable style={styles.fab} onPress={() => setShowAdd(true)}><Plus color="white" size={25} /></Pressable>
  </View><AddTransactionModal visible={showAdd} accounts={store.accounts} categories={store.categories} onClose={() => setShowAdd(false)} onSave={addTransaction} /><AccountEditor visible={showAccountEditor} account={editingAccount} onClose={() => { setShowAccountEditor(false); setEditingAccount(undefined); }} onSave={saveAccount} /><TransactionDetailsModal transaction={selectedTransaction} onClose={() => setSelectedTransaction(undefined)} onEdit={() => { setEditingTransaction(selectedTransaction); setSelectedTransaction(undefined); }} onDelete={deleteTransaction} /><TransactionEditor visible={Boolean(editingTransaction)} transaction={editingTransaction} accounts={store.accounts} categories={store.categories} onClose={() => setEditingTransaction(undefined)} onSave={updateTransaction} />{saved && <View style={styles.toast}><Text style={styles.toastText}>Transaction updated</Text></View>}</SafeAreaView>;
}

function Dashboard({ store, total, income, expenses, onAdd, onAccounts, onTransactions, onTransaction }: { store: Store; total: number; income: number; expenses: number; onAdd: () => void; onAccounts: () => void; onTransactions: () => void; onTransaction: (transaction: Transaction) => void }) { return <ScrollView contentContainerStyle={styles.scroll} showsVerticalScrollIndicator={false}>
  <View style={styles.balanceCard}><View style={styles.balanceHeader}><Text style={styles.cardKicker}>TOTAL BALANCE</Text><MoreHorizontal color="white" size={22} /></View><Text style={styles.balance}>{formatMoney(total)}</Text><View style={styles.balanceFooter}><View style={styles.trend}><ArrowUpRight color={palette.green} size={15} /><Text style={styles.trendText}>+12.8%</Text><Text style={styles.trendMuted}> this month</Text></View><Text style={styles.balanceLabel}>Across 3 accounts</Text></View></View>
  <View style={styles.statRow}><Stat label="Income" value={income} icon={<ArrowDownLeft color={palette.green} size={16} />} /><Stat label="Spending" value={expenses} icon={<ArrowUpRight color={palette.coral} size={16} />} /></View>
  <Section title="Your accounts" onPress={onAccounts} /><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.accountScroller}>{store.accounts.map(account => <AccountCard key={account.id} account={account} />)}<Pressable style={styles.addAccountCard} onPress={onAdd}><Plus color={palette.green} size={20} /><Text style={styles.addAccountText}>Add account</Text></Pressable></ScrollView>
  <Section title="Recent activity" onPress={onTransactions} /><View style={styles.transactionList}>{store.transactions.slice(0, 4).map(item => <TransactionRow key={item.id} item={item} onPress={() => onTransaction(item)} />)}</View>
  <View style={styles.insight}><Text style={styles.insightMark}>i</Text><View style={{ flex: 1 }}><Text style={styles.insightTitle}>Your spending is looking good</Text><Text style={styles.insightCopy}>You spent 18% less than last week.</Text></View><ChevronRight size={18} color={palette.navy} /></View>
</ScrollView>; }
function Section({ title, onPress }: { title: string; onPress?: () => void }) { return <View style={styles.sectionHeader}><Text style={styles.sectionTitle}>{title}</Text><Pressable onPress={onPress} disabled={!onPress}><Text style={styles.link}>See all</Text></Pressable></View>; }
function Stat({ label, value, icon }: { label: string; value: number; icon: React.ReactNode }) { return <View style={styles.stat}><View style={styles.statTop}><Text style={styles.statLabel}>{label}</Text><View style={styles.statIcon}>{icon}</View></View><Text style={styles.statValue}>{formatMoney(value)}</Text><Text style={styles.statCaption}>This month</Text></View>; }
function AccountCard({ account }: { account: Account }) { return <View style={[styles.accountCard, { backgroundColor: account.color }]}><View style={styles.accountCardTop}>{account.type === 'cash' ? <Banknote color="white" size={19} /> : account.type === 'bank' ? <Landmark color="white" size={19} /> : <CreditCard color="white" size={19} />}<MoreHorizontal color="rgba(255,255,255,.7)" size={19} /></View><Text style={styles.accountName}>{account.name}</Text><Text style={styles.accountBalance}>{formatMoney(account.balance)}</Text>{account.last4 && <Text style={styles.last4}>•••• {account.last4}</Text>}</View>; }
function TransactionRow({ item, onPress }: { item: Transaction; onPress?: () => void }) { return <Pressable onPress={onPress} style={styles.transaction}><View style={styles.transactionIcon}><Icon kind={item.icon} /></View><View style={styles.transactionMain}><Text style={styles.transactionTitle}>{item.title}</Text><Text style={styles.transactionMeta}>{item.category} · {item.date}</Text></View><Text style={[styles.transactionAmount, { color: item.amount > 0 ? palette.green : palette.ink }]}>{item.amount > 0 ? '+' : ''}{formatMoney(item.amount)}</Text></Pressable>; }
function TransactionDetailsModal({ transaction, onClose, onEdit, onDelete }: { transaction?: Transaction; onClose: () => void; onEdit: () => void; onDelete: (transaction: Transaction) => void }) { if (!transaction) return null; return <Modal visible animationType="slide" transparent onRequestClose={onClose}><View style={styles.modalBackdrop}><View style={transactionStyles.detailSheet}><View style={styles.modalTitleRow}><Text style={styles.modalEyebrow}>TRANSACTION DETAILS</Text><Pressable onPress={onClose}><X color={palette.ink} /></Pressable></View><View style={transactionStyles.detailHeader}><View style={transactionStyles.detailIcon}><Icon kind={transaction.icon} /></View><View><Text style={transactionStyles.detailTitle}>{transaction.title}</Text><Text style={transactionStyles.detailCategory}>{transaction.category}</Text></View></View><Text style={[transactionStyles.detailAmount, { color: transaction.amount > 0 ? palette.green : palette.ink }]}>{transaction.amount > 0 ? '+' : ''}{formatMoney(transaction.amount)}</Text><View style={transactionStyles.detailLine}><Text style={transactionStyles.detailLabel}>Account</Text><Text style={transactionStyles.detailValue}>{transaction.account}</Text></View><View style={transactionStyles.detailLine}><Text style={transactionStyles.detailLabel}>Date</Text><Text style={transactionStyles.detailValue}>{transaction.date}</Text></View><View style={transactionStyles.actionRow}><Pressable style={transactionStyles.editButton} onPress={onEdit}><Text style={transactionStyles.editButtonText}>Edit transaction</Text></Pressable><Pressable style={transactionStyles.deleteButton} onPress={() => Alert.alert('Delete transaction?', 'This will also restore the account balance.', [{ text: 'Cancel', style: 'cancel' }, { text: 'Delete', style: 'destructive', onPress: () => onDelete(transaction) }])}><Text style={transactionStyles.deleteButtonText}>Delete</Text></Pressable></View></View></View></Modal>; }
function TransactionEditor({ visible, transaction, accounts, categories, onClose, onSave }: { visible: boolean; transaction?: Transaction; accounts: Account[]; categories: Category[]; onClose: () => void; onSave: (transaction: Transaction, title: string, amount: number, type: 'expense' | 'income', accountId: string, categoryId: string) => void }) { const [type, setType] = useState<'expense' | 'income'>('expense'); const [title, setTitle] = useState(''); const [amount, setAmount] = useState(''); const [accountId, setAccountId] = useState(''); const [categoryId, setCategoryId] = useState(''); useEffect(() => { if (!transaction) return; setType(transaction.type === 'income' ? 'income' : 'expense'); setTitle(transaction.title); setAmount(Math.abs(transaction.amount).toString()); setAccountId(transaction.accountId ?? accounts.find(account => account.name === transaction.account)?.id ?? accounts[0]?.id ?? ''); setCategoryId(transaction.categoryId ?? categories.find(category => category.name === transaction.category)?.id ?? ''); }, [transaction, visible, accounts, categories]); const filteredCategories = categories.filter(item => item.kind === type || item.kind === 'both'); useEffect(() => { if (!filteredCategories.some(item => item.id === categoryId)) setCategoryId(filteredCategories[0]?.id ?? ''); }, [type, categories, categoryId]); if (!transaction) return null; return <Modal visible={visible} animationType="slide" transparent onRequestClose={onClose}><View style={styles.modalBackdrop}><View style={styles.sheet}><View style={styles.modalTitleRow}><View><Text style={styles.modalEyebrow}>EDIT ENTRY</Text><Text style={styles.modalTitle}>Edit transaction</Text></View><Pressable onPress={onClose}><X color={palette.ink} /></Pressable></View><View style={styles.typeToggle}>{(['expense', 'income'] as const).map(item => <Pressable key={item} onPress={() => setType(item)} style={[styles.typeOption, type === item && styles.typeActive]}><Text style={[styles.typeText, type === item && styles.typeTextActive]}>{item[0].toUpperCase() + item.slice(1)}</Text></Pressable>)}</View><Text style={styles.inputLabel}>Amount</Text><TextInput keyboardType="decimal-pad" value={amount} onChangeText={setAmount} style={styles.amountInput} /><Text style={styles.inputLabel}>Description</Text><TextInput value={title} onChangeText={setTitle} style={styles.field} /><Text style={styles.inputLabel}>Category</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={transactionStyles.selectorRow}>{filteredCategories.map(category => <Pressable key={category.id} onPress={() => setCategoryId(category.id)} style={[transactionStyles.selectorChip, category.id === categoryId && transactionStyles.selectorChipActive]}><Text style={[transactionStyles.selectorText, category.id === categoryId && transactionStyles.selectorTextActive]}>{category.name}</Text></Pressable>)}</ScrollView><Text style={styles.inputLabel}>Account</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={transactionStyles.selectorRow}>{accounts.map(account => <Pressable key={account.id} onPress={() => setAccountId(account.id)} style={[transactionStyles.selectorChip, account.id === accountId && transactionStyles.selectorChipActive]}><Text style={[transactionStyles.selectorText, account.id === accountId && transactionStyles.selectorTextActive]}>{account.name}</Text></Pressable>)}</ScrollView><Pressable disabled={!title.trim() || !amount || !accountId || !categoryId} onPress={() => onSave(transaction, title.trim(), Number(amount), type, accountId, categoryId)} style={[styles.saveButton, (!title.trim() || !amount || !accountId || !categoryId) && styles.saveDisabled]}><Text style={styles.saveText}>Save changes</Text></Pressable></View></View></Modal>; }
function Activity({ transactions, onTransaction }: { transactions: Transaction[]; onTransaction: (transaction: Transaction) => void }) { const [query, setQuery] = useState(''); const filtered = transactions.filter(item => item.title.toLowerCase().includes(query.toLowerCase())); return <View style={styles.page}><Text style={styles.pageTitle}>Activity</Text><Text style={styles.pageSubtitle}>Everything in one place</Text><View style={styles.search}><Search size={18} color={palette.muted} /><TextInput placeholder="Search transactions" placeholderTextColor={palette.muted} value={query} onChangeText={setQuery} style={styles.searchInput} /></View><View style={styles.filterRow}>{['All', 'Expenses', 'Income'].map((item, index) => <Pressable key={item} style={[styles.filterChip, index === 0 && styles.filterChipActive]}><Text style={[styles.filterText, index === 0 && styles.filterTextActive]}>{item}</Text></Pressable>)}</View><ScrollView showsVerticalScrollIndicator={false}>{filtered.map(item => <TransactionRow key={item.id} item={item} onPress={() => onTransaction(item)} />)}</ScrollView></View>; }
function Accounts({ accounts, onAdd, onEdit, onDelete }: { accounts: Account[]; onAdd: () => void; onEdit: (account: Account) => void; onDelete: (id: string) => void }) { return <ScrollView contentContainerStyle={styles.page} showsVerticalScrollIndicator={false}><View style={styles.pageTitleRow}><View><Text style={styles.pageTitle}>Accounts</Text><Text style={styles.pageSubtitle}>Keep your money organised</Text></View><Pressable style={styles.smallAdd} onPress={onAdd}><Plus color="white" size={18} /></Pressable></View><View style={styles.accountTotal}><Text style={styles.statLabel}>NET WORTH</Text><Text style={styles.netWorth}>{formatMoney(accounts.reduce((sum, item) => sum + item.balance, 0))}</Text><Text style={styles.statCaption}>Updated just now</Text></View>{accounts.map(account => <View key={account.id} style={styles.accountLine}><View style={[styles.accountLineIcon, { backgroundColor: `${account.color}18` }]}>{account.type === 'cash' ? <Banknote color={account.color} size={21} /> : account.type === 'bank' ? <Landmark color={account.color} size={21} /> : <CreditCard color={account.color} size={21} />}</View><View style={{ flex: 1 }}><Text style={styles.transactionTitle}>{account.name}</Text><Text style={styles.transactionMeta}>{account.type.toUpperCase()} {account.last4 ? `· •••• ${account.last4}` : ''}</Text></View><Text style={styles.accountLineBalance}>{formatMoney(account.balance)}</Text><Pressable onPress={() => onEdit(account)} style={styles.rowAction}><Pencil color={palette.navy} size={16} /></Pressable><Pressable onPress={() => Alert.alert('Delete account?', `${account.name} will be removed from your accounts.`, [{ text: 'Cancel', style: 'cancel' }, { text: 'Delete', style: 'destructive', onPress: () => onDelete(account.id) }])} style={styles.rowAction}><Trash2 color={palette.coral} size={16} /></Pressable></View>)}</ScrollView>; }
function InsightsPage({ transactions, onBack }: { transactions: Transaction[]; onBack: () => void }) { const [mode, setMode] = useState<'expense' | 'income'>('expense'); const entries = transactions.filter(item => item.type === mode); const totals = entries.reduce<Record<string, number>>((result, item) => { result[item.category] = (result[item.category] ?? 0) + Math.abs(item.amount); return result; }, {}); const rows = Object.entries(totals).sort(([, first], [, second]) => second - first); const total = rows.reduce((sum, [, value]) => sum + value, 0); const max = rows[0]?.[1] ?? 1; return <ScrollView contentContainerStyle={styles.page} showsVerticalScrollIndicator={false}><Pressable style={settingsStyles.backButton} onPress={onBack}><ChevronLeft color={palette.ink} size={18} /><Text style={settingsStyles.backText}>Settings</Text></Pressable><Text style={styles.pageTitle}>Insights</Text><Text style={styles.pageSubtitle}>Understand where your money moves</Text><View style={settingsStyles.analyticsToggle}>{(['expense', 'income'] as const).map(item => <Pressable key={item} onPress={() => setMode(item)} style={[settingsStyles.analyticsOption, mode === item && settingsStyles.analyticsOptionActive]}><Text style={[settingsStyles.analyticsText, mode === item && settingsStyles.analyticsTextActive]}>{item === 'expense' ? 'Expenses' : 'Income'}</Text></Pressable>)}</View><View style={settingsStyles.analyticsTotal}><Text style={styles.statLabel}>{mode === 'expense' ? 'TOTAL EXPENSES' : 'TOTAL INCOME'}</Text><Text style={styles.netWorth}>{formatMoney(total)}</Text><Text style={styles.statCaption}>{entries.length} transaction{entries.length === 1 ? '' : 's'} · All time</Text></View><Text style={settingsStyles.sectionLabel}>BY CATEGORY</Text>{rows.length ? <View style={settingsStyles.analyticsPanel}>{rows.map(([category, value]) => <View key={category} style={settingsStyles.analyticsRow}><View style={settingsStyles.analyticsRowTop}><Text style={styles.transactionTitle}>{category}</Text><Text style={settingsStyles.analyticsValue}>{formatMoney(value)}</Text></View><View style={settingsStyles.track}><View style={[settingsStyles.fill, { width: `${Math.max((value / max) * 100, 5)}%`, backgroundColor: mode === 'expense' ? palette.coral : palette.green }]} /></View></View>)}</View> : <View style={settingsStyles.emptyState}><Text style={settingsStyles.emptyTitle}>No {mode} categories yet</Text><Text style={settingsStyles.panelCopy}>Add a {mode} transaction to see it here.</Text></View>}</ScrollView>; }
function ProfileSettings({ profile, onProfileChange, onCategories, onInsights }: { profile: Profile; onProfileChange: (profile: Profile) => void; onCategories: () => void; onInsights: () => void }) { const [name, setName] = useState(profile.name); const [email, setEmail] = useState(profile.email); useEffect(() => { setName(profile.name); setEmail(profile.email); }, [profile]); function saveProfile() { if (name.trim() && email.trim()) onProfileChange({ name: name.trim(), email: email.trim() }); } return <ScrollView contentContainerStyle={styles.page} showsVerticalScrollIndicator={false}><Text style={styles.pageTitle}>Settings</Text><Text style={styles.pageSubtitle}>Your profile and preferences</Text><View style={settingsStyles.profileHeader}><View style={settingsStyles.avatar}><Text style={settingsStyles.avatarText}>{(name.trim() || 'M').slice(0, 1).toUpperCase()}</Text></View><View><Text style={settingsStyles.profileName}>{name || 'Your name'}</Text><Text style={settingsStyles.profileEmail}>{email || 'Add your email'}</Text></View></View><Text style={settingsStyles.sectionLabel}>PROFILE DETAILS</Text><View style={settingsStyles.profilePanel}><Text style={styles.inputLabel}>Name</Text><TextInput value={name} onChangeText={setName} placeholder="Your name" placeholderTextColor={palette.muted} style={styles.field} /><Text style={styles.inputLabel}>Email</Text><TextInput value={email} onChangeText={setEmail} keyboardType="email-address" autoCapitalize="none" placeholder="you@example.com" placeholderTextColor={palette.muted} style={styles.field} /><Pressable disabled={!name.trim() || !email.trim()} onPress={saveProfile} style={[styles.saveButton, (!name.trim() || !email.trim()) && styles.saveDisabled]}><Text style={styles.saveText}>Save profile</Text></Pressable></View><Text style={settingsStyles.sectionLabel}>MANAGE</Text><Pressable style={settingsStyles.menuButton} onPress={onCategories}><View style={settingsStyles.menuIcon}><Text style={settingsStyles.menuIconText}>#</Text></View><View style={{ flex: 1 }}><Text style={settingsStyles.menuTitle}>Categories</Text><Text style={settingsStyles.panelCopy}>Add and organise expense categories</Text></View><ChevronRight color={palette.muted} size={19} /></Pressable><Pressable style={settingsStyles.menuButton} onPress={onInsights}><View style={[settingsStyles.menuIcon, { backgroundColor: '#EAF0F4' }]}><Text style={[settingsStyles.menuIconText, { color: palette.navy }]}>↗</Text></View><View style={{ flex: 1 }}><Text style={settingsStyles.menuTitle}>Insights</Text><Text style={settingsStyles.panelCopy}>See category-wise income and expenses</Text></View><ChevronRight color={palette.muted} size={19} /></Pressable><View style={settingsStyles.preference}><Text style={styles.sectionTitle}>Currency</Text><Text style={settingsStyles.panelCopy}>Indian Rupee · INR</Text><ChevronRight color={palette.muted} size={18} /></View></ScrollView>; }
function CategoriesPage({ categories, onChange, onBack }: { categories: Category[]; onChange: (categories: Category[]) => void; onBack: () => void }) { const [editorOpen, setEditorOpen] = useState(false); const [editing, setEditing] = useState<Category | undefined>(); function saveCategory(category: Omit<Category, 'id'>, id?: string) { onChange(id ? categories.map(item => item.id === id ? { ...item, ...category } : item) : [...categories, { ...category, id: Date.now().toString() }]); setEditorOpen(false); setEditing(undefined); } function deleteCategory(category: Category) { Alert.alert('Delete category?', `${category.name} will be removed.`, [{ text: 'Cancel', style: 'cancel' }, { text: 'Delete', style: 'destructive', onPress: () => onChange(categories.filter(item => item.id !== category.id)) }]); } return <View style={styles.page}><Pressable style={settingsStyles.backButton} onPress={onBack}><ChevronLeft color={palette.ink} size={18} /><Text style={settingsStyles.backText}>Settings</Text></Pressable><View style={styles.pageTitleRow}><View><Text style={styles.pageTitle}>Categories</Text><Text style={styles.pageSubtitle}>Organise expenses your way</Text></View><Pressable style={styles.smallAdd} onPress={() => { setEditing(undefined); setEditorOpen(true); }}><Plus color="white" size={18} /></Pressable></View><View style={settingsStyles.panel}>{categories.map(category => <View key={category.id} style={settingsStyles.categoryRow}><View style={[settingsStyles.categoryIcon, { backgroundColor: `${category.color}20` }]}><Text style={{ color: category.color, fontSize: 16 }}>{category.icon === 'utensils' ? '✦' : category.icon === 'home' ? '⌂' : category.icon === 'bag' ? '□' : '○'}</Text></View><Text style={settingsStyles.categoryName}>{category.name}</Text><Pressable onPress={() => { setEditing(category); setEditorOpen(true); }} style={settingsStyles.categoryAction}><Pencil color={palette.navy} size={16} /></Pressable><Pressable onPress={() => deleteCategory(category)} style={settingsStyles.categoryAction}><Trash2 color={palette.coral} size={16} /></Pressable></View>)}</View><CategoryEditor visible={editorOpen} category={editing} onClose={() => { setEditorOpen(false); setEditing(undefined); }} onSave={saveCategory} /></View>; }
function CategoryEditor({ visible, category, onClose, onSave }: { visible: boolean; category?: Category; onClose: () => void; onSave: (category: Omit<Category, 'id'>, id?: string) => void }) { const [name, setName] = useState(''); const [icon, setIcon] = useState('tag'); const [color, setColor] = useState('#49A078'); const [kind, setKind] = useState<Category['kind']>('expense'); useEffect(() => { setName(category?.name ?? ''); setIcon(category?.icon ?? 'tag'); setColor(category?.color ?? '#49A078'); setKind(category?.kind ?? 'expense'); }, [category, visible]); const colors = ['#49A078', '#E9785F', '#6D8EAD', '#D69E4B', '#8B72A8']; return <Modal visible={visible} animationType="slide" transparent onRequestClose={onClose}><View style={styles.modalBackdrop}><View style={styles.sheet}><View style={styles.modalTitleRow}><View><Text style={styles.modalEyebrow}>{category ? 'EDIT CATEGORY' : 'NEW CATEGORY'}</Text><Text style={styles.modalTitle}>{category ? 'Edit category' : 'Add category'}</Text></View><Pressable onPress={onClose}><X color={palette.ink} /></Pressable></View><Text style={styles.inputLabel}>Category name</Text><TextInput value={name} onChangeText={setName} placeholder="e.g. Subscriptions" placeholderTextColor={palette.muted} style={styles.field} /><Text style={styles.inputLabel}>Used for</Text><View style={styles.typeToggle}>{(['expense', 'income', 'both'] as const).map(item => <Pressable key={item} onPress={() => setKind(item)} style={[styles.typeOption, kind === item && styles.typeActive]}><Text style={[styles.typeText, kind === item && styles.typeTextActive]}>{item[0].toUpperCase() + item.slice(1)}</Text></Pressable>)}</View><Text style={styles.inputLabel}>Icon name</Text><TextInput value={icon} onChangeText={setIcon} placeholder="e.g. tag" placeholderTextColor={palette.muted} style={styles.field} /><Text style={styles.inputLabel}>Colour</Text><View style={settingsStyles.colorRow}>{colors.map(item => <Pressable key={item} onPress={() => setColor(item)} style={[settingsStyles.colorChoice, { backgroundColor: item }, color === item && settingsStyles.colorChoiceActive]} />)}</View><Pressable disabled={!name.trim()} onPress={() => onSave({ name: name.trim(), icon: icon.trim() || 'tag', color, kind }, category?.id)} style={[styles.saveButton, !name.trim() && styles.saveDisabled]}><Text style={styles.saveText}>{category ? 'Save changes' : 'Add category'}</Text></Pressable></View></View></Modal>; }
function AccountEditor({ visible, account, onClose, onSave }: { visible: boolean; account?: Account; onClose: () => void; onSave: (account: Omit<Account, 'id'>, id?: string) => void }) { const [name, setName] = useState(''); const [type, setType] = useState<Account['type']>('cash'); const [balance, setBalance] = useState(''); useEffect(() => { setName(account?.name ?? ''); setType(account?.type ?? 'cash'); setBalance(account?.balance.toString() ?? ''); }, [account, visible]); const color = type === 'cash' ? palette.green : type === 'bank' ? palette.navy : palette.coral; return <Modal visible={visible} animationType="slide" transparent onRequestClose={onClose}><View style={styles.modalBackdrop}><View style={styles.sheet}><View style={styles.modalTitleRow}><View><Text style={styles.modalEyebrow}>{account ? 'EDIT ACCOUNT' : 'NEW ACCOUNT'}</Text><Text style={styles.modalTitle}>{account ? 'Edit account' : 'Add account'}</Text></View><Pressable onPress={onClose}><X color={palette.ink} /></Pressable></View><Text style={styles.inputLabel}>Account name</Text><TextInput value={name} onChangeText={setName} placeholder="e.g. Savings account" placeholderTextColor={palette.muted} style={styles.field} /><Text style={styles.inputLabel}>Type</Text><View style={styles.typeToggle}>{(['cash', 'bank', 'card'] as const).map(item => <Pressable key={item} onPress={() => setType(item)} style={[styles.typeOption, type === item && styles.typeActive]}><Text style={[styles.typeText, type === item && styles.typeTextActive]}>{item[0].toUpperCase() + item.slice(1)}</Text></Pressable>)}</View><Text style={styles.inputLabel}>Current balance</Text><TextInput value={balance} onChangeText={setBalance} keyboardType="decimal-pad" placeholder="₹ 0" placeholderTextColor={palette.muted} style={styles.field} /><Pressable disabled={!name.trim() || !balance || Number.isNaN(Number(balance))} onPress={() => onSave({ name: name.trim(), type, balance: Number(balance), color, last4: account?.last4 }, account?.id)} style={[styles.saveButton, (!name.trim() || !balance || Number.isNaN(Number(balance))) && styles.saveDisabled]}><Text style={styles.saveText}>{account ? 'Save changes' : 'Add account'}</Text></Pressable></View></View></Modal>; }
function AddTransactionModal({ visible, accounts, categories, onClose, onSave }: { visible: boolean; accounts: Account[]; categories: Category[]; onClose: () => void; onSave: (title: string, amount: number, type: 'expense' | 'income', accountId: string, categoryId: string) => void }) { const [type, setType] = useState<'expense' | 'income'>('expense'); const [title, setTitle] = useState(''); const [amount, setAmount] = useState(''); const [accountId, setAccountId] = useState(''); const [categoryId, setCategoryId] = useState(''); const [accountMenuOpen, setAccountMenuOpen] = useState(false); const filteredCategories = categories.filter(item => item.kind === type || item.kind === 'both'); useEffect(() => { if (visible && accounts.length && !accounts.some(item => item.id === accountId)) setAccountId(accounts[0].id); }, [visible, accounts, accountId]); useEffect(() => { if (!filteredCategories.some(item => item.id === categoryId)) setCategoryId(filteredCategories[0]?.id ?? ''); }, [type, categories, categoryId]); const selectedAccount = accounts.find(item => item.id === accountId) ?? accounts[0]; const selectedCategory = filteredCategories.find(item => item.id === categoryId); return <Modal visible={visible} animationType="slide" transparent onRequestClose={onClose}><View style={styles.modalBackdrop}><View style={styles.sheet}><View style={styles.modalTitleRow}><View><Text style={styles.modalEyebrow}>NEW ENTRY</Text><Text style={styles.modalTitle}>Add transaction</Text></View><Pressable onPress={onClose}><X color={palette.ink} /></Pressable></View><View style={styles.typeToggle}>{(['expense', 'income'] as const).map(item => <Pressable key={item} onPress={() => setType(item)} style={[styles.typeOption, type === item && styles.typeActive]}><Text style={[styles.typeText, type === item && styles.typeTextActive]}>{item[0].toUpperCase() + item.slice(1)}</Text></Pressable>)}</View><Text style={styles.inputLabel}>Amount</Text><TextInput keyboardType="decimal-pad" value={amount} onChangeText={setAmount} placeholder="₹ 0" placeholderTextColor={palette.muted} style={styles.amountInput} /><Text style={styles.inputLabel}>What was this for?</Text><TextInput value={title} onChangeText={setTitle} placeholder="e.g. Dinner with friends" placeholderTextColor={palette.muted} style={styles.field} /><Text style={styles.inputLabel}>Category</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={settingsStyles.categoryOptions}>{filteredCategories.map(category => <Pressable key={category.id} onPress={() => setCategoryId(category.id)} style={[settingsStyles.categoryOption, category.id === categoryId && settingsStyles.categoryOptionActive]}><Text style={[settingsStyles.categoryOptionText, category.id === categoryId && settingsStyles.categoryOptionTextActive]}>{category.name}</Text></Pressable>)}</ScrollView><Text style={styles.inputLabel}>Account</Text><Pressable style={styles.selectedAccount} onPress={() => setAccountMenuOpen(open => !open)}><Wallet color={selectedAccount?.color ?? palette.green} size={18} /><Text style={styles.selectedAccountText}>{selectedAccount?.name ?? 'Select account'}</Text><ChevronRight color={palette.muted} size={17} style={accountMenuOpen ? { transform: [{ rotate: '90deg' }] } : undefined} /></Pressable>{accountMenuOpen && <View style={pickerStyles.accountMenu}>{accounts.map(account => <Pressable key={account.id} onPress={() => { setAccountId(account.id); setAccountMenuOpen(false); }} style={[pickerStyles.accountOption, account.id === accountId && pickerStyles.accountOptionActive]}><View style={[pickerStyles.accountOptionDot, { backgroundColor: account.color }]} /><Text style={pickerStyles.accountOptionText}>{account.name}</Text><Text style={pickerStyles.accountOptionBalance}>{formatMoney(account.balance)}</Text></Pressable>)}</View>}<Pressable disabled={!title || !amount || !selectedAccount || !selectedCategory} onPress={() => onSave(title, Number(amount), type, accountId, categoryId)} style={[styles.saveButton, (!title || !amount || !selectedAccount || !selectedCategory) && styles.saveDisabled]}><Text style={styles.saveText}>Save transaction</Text></Pressable></View></View></Modal>; }

